#include <map>
#include <chrono>

void measure_lookup(std::map<int, int>& m, int key) {
    auto start = std::chrono::high_resolution_clock::now();
    m.find(key); // O(log N) lookup
    auto end = std::chrono::high_resolution_clock::now();
    // Time taken will scale logarithmically with m.size()
}

int main() {
    std::map<int, int> data;
    // O(log N) insertion
    for (int i = 0; i < 100000; ++i) {
        data.insert({i, i * 2}); 
    }
    measure_lookup(data, 50000);
}
